using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.Z },
        new SkillSlot { keyBinding = KeyCode.X },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（槽位 0~3，留空则不装备）")]
    [SerializeField] private string _initialSkillId0;
    [SerializeField] private string _initialSkillId1;
    [SerializeField] private string _initialSkillId2;
    [SerializeField] private string _initialSkillId3;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkills();
    }

    private void EquipInitialSkills()
    {
        var ids = new[] { _initialSkillId0, _initialSkillId1, _initialSkillId2, _initialSkillId3 };
        for (int i = 0; i < ids.Length; i++)
        {
            if (!string.IsNullOrEmpty(ids[i]))
                EquipSkill(i, ids[i]);
        }
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 下一层出口 — Boss/Exit 房间清空后出现。
/// 玩家触碰后加载指定场景。
/// </summary>
[RequireComponent(typeof(Collider2D))]
public class NextLevelExit : MonoBehaviour
{
    [Tooltip("目标场景名 (在 Build Settings 中)，如果为空则进入胜利界面")]
    public string nextSceneName;
    public string winningSceneName = "Winning";

    private void Awake()
    {
        var col = GetComponent<Collider2D>();
        col.isTrigger = true;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!other.CompareTag("Player")) return;
        if (other.GetComponent<PlayerStats>() == null) return;

        // 如果为空则进入胜利界面
        if (string.IsNullOrEmpty(nextSceneName))
        {
            if (string.IsNullOrEmpty(winningSceneName))
            {
                if (!Application.CanStreamedLevelBeLoaded(winningSceneName))
                {
                    Debug.LogError($"场景 '{winningSceneName}' 未在 Build Settings 中添加或启用，无法加载！");
                    return; // 直接返回，不会触发报错
                }
                Debug.LogWarning("NextLevelExit: nextSceneName 为空");
                return;
            }

            SceneManager.LoadScene(winningSceneName);
            return;
        }

        if (!Application.CanStreamedLevelBeLoaded(nextSceneName))
        {
            Debug.LogError($"场景 '{nextSceneName}' 未在 Build Settings 中添加或启用，无法加载！");
            return; // 直接返回，不会触发报错
        }

        // 确保 Player 在跨场景切换时不被销毁 (与 PlayerManager 协同工作)
        DontDestroyOnLoad(other.gameObject);

        SceneManager.LoadScene(nextSceneName);
        return;
    }
}

using UnityEngine;

/// <summary>
/// 道具 UI Controller — 监听 ItemManager(Model), 通知 ItemPanel(View)。
/// 本类是 Model ↔ View 的唯一耦合点, 沿用 SkillUIController 的模式。
/// </summary>
public class ItemUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private ItemManager _itemManager;

    [Header("View 引用")]
    [SerializeField] private ItemPanel _panel;

    [Header("初始容量")]
    [SerializeField] private int _initialSlotCount = 16;

    // ==================== 生命周期 ====================

    private void Start()
    {
        if (_itemManager == null)
            _itemManager = ResolveItemManager();

        if (_itemManager == null)
        {
            Debug.LogError("ItemUIController: ItemManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("ItemUIController: ItemPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_initialSlotCount);

        _itemManager.OnItemAcquired += HandleItemAcquired;
        _itemManager.OnItemRemoved += HandleItemRemoved;

        SyncAll();
    }

    private void OnDestroy()
    {
        if (_itemManager != null)
        {
            _itemManager.OnItemAcquired -= HandleItemAcquired;
            _itemManager.OnItemRemoved -= HandleItemRemoved;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleItemAcquired(ItemData item)
    {
        // 找到该道具在列表中的索引
        var items = _itemManager.Items;
        int idx = -1;
        for (int i = 0; i < items.Count; i++)
        {
            if (items[i] == item) { idx = i; break; }
        }
        if (idx >= 0) SyncSlot(idx, item);
    }

    private void HandleItemRemoved(ItemData item)
    {
        SyncAll();
    }

    // ==================== 核心同步 ====================

    private void SyncAll()
    {
        var items = _itemManager.Items;
        for (int i = 0; i < items.Count; i++)
            SyncSlot(i, items[i]);

        // 隐藏空槽
        for (int i = items.Count; i < _initialSlotCount; i++)
            _panel.ClearSlot(i);
    }

    private void SyncSlot(int index, ItemData item)
    {
        int count = _itemManager.GetItemCount(item.itemId);
        ItemViewData data = new ItemViewData
        {
            Icon = item.icon,
            Name = item.itemName,
            Description = item.description,
            Quality = item.quality,
            Count = count
        };
        _panel.RefreshSlot(index, data, item);
    }

    // ==================== 查找 ====================

    private static ItemManager ResolveItemManager()
    {
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<ItemManager>();

        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<ItemManager>() : null;
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 商店购买弹窗 — 玩家靠近标记为 IsShopItem 的 ItemPickup 时悬浮显示。
/// 显示道具信息 + 价格 + 购买按钮。
/// Screen Space Overlay，跟随拾取物世界坐标。
/// </summary>
public class ShopItemPurchasePopup : MonoBehaviour
{
    [Header("UI 元素")]
    [SerializeField] private CanvasGroup _canvasGroup;
    [SerializeField] private Image _background;
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _descText;
    [SerializeField] private TMP_Text _priceText;
    [SerializeField] private TMP_Text _promptText;
    [SerializeField] private Button _buyButton;

    [Header("样式")]
    [SerializeField] private float _fadeSpeed = 10f;
    [SerializeField] private Vector2 _screenOffset = new Vector2(0, 100f);

    [Header("购买按键")]
    [SerializeField] private KeyCode _buyKey = KeyCode.F;

    /// <summary>当前正在展示的拾取物</summary>
    public ItemPickup CurrentTarget { get; private set; }

    public bool IsVisible { get; private set; }

    private RectTransform _rect;
    private Camera _mainCam;

    private void Awake()
    {
        _rect = GetComponent<RectTransform>();
        _mainCam = Camera.main;
        if (_canvasGroup != null) _canvasGroup.alpha = 0f;

        if (_buyButton != null)
            _buyButton.onClick.AddListener(OnBuyClicked);

        gameObject.SetActive(false);
    }

    private void Update()
    {
        if (CurrentTarget == null || !IsVisible) return;

        // F 键购买
        if (Input.GetKeyDown(_buyKey))
        {
            // 购买由 ItemInteractionHandler 统一处理 F 键
            // 这里只做按钮点击的备选
            OnBuyClicked();
        }
    }

    private void LateUpdate()
    {
        if (CurrentTarget == null || !IsVisible)
        {
            if (_canvasGroup != null && _canvasGroup.alpha > 0f)
                _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 0f, _fadeSpeed * Time.deltaTime);
            return;
        }

        // 跟随世界坐标
        if (_mainCam != null)
        {
            Vector3 screenPos = _mainCam.WorldToScreenPoint(CurrentTarget.transform.position);
            _rect.position = screenPos + (Vector3)_screenOffset;
        }

        if (_canvasGroup != null)
            _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 1f, _fadeSpeed * Time.deltaTime);
    }

    /// <summary>显示弹窗</summary>
    public void Show(ItemPickup pickup)
    {
        if (pickup == null || pickup.itemData == null) return;

        // 如果正在显示另一个，先隐藏
        if (CurrentTarget != null && CurrentTarget != pickup)
            Hide();

        CurrentTarget = pickup;
        gameObject.SetActive(true);
        IsVisible = true;

        var data = pickup.itemData;

        if (_icon != null)
        {
            _icon.sprite = data.icon;
            _icon.enabled = data.icon != null;
        }
        if (_nameText != null)
        {
            _nameText.text = data.itemName;
            _nameText.color = ItemPickup.QualityToColor(data.quality);
        }
        if (_descText != null)
            _descText.text = data.description;

        RefreshPrice(pickup);

        if (_background != null)
            _background.color = new Color(0.05f, 0.05f, 0.1f, 0.92f);
    }

    /// <summary>隐藏弹窗</summary>
    public void Hide()
    {
        CurrentTarget = null;
        IsVisible = false;
        gameObject.SetActive(false);
    }

    /// <summary>刷新价格显示（ATP 变化时由 ItemInteractionHandler 调用）</summary>
    public void RefreshPrice(ItemPickup pickup)
    {
        if (pickup == null) return;

        int price = pickup.ShopPrice;
        var cm = ResolveCurrencyManager();

        bool canAfford = cm != null && cm.ATP >= price;
        int currentATP = cm != null ? cm.ATP : 0;

        if (_priceText != null)
        {
            _priceText.text = canAfford
                ? $"<color=#D9AA4D>{price} ATP</color>"
                : $"<color=#FF4444>{price} ATP</color>  (当前: {currentATP})";
        }

        if (_promptText != null)
        {
            _promptText.text = canAfford
                ? $"[F] 购买"
                : $"<color=#FF4444>ATP 不足</color>";
        }

        if (_buyButton != null)
            _buyButton.interactable = canAfford;
    }

    private void OnBuyClicked()
    {
        if (CurrentTarget == null) return;

        // 直接执行购买逻辑
        var player = PlayerManager.Instance?.CurrentPlayer;
        if (player == null) player = GameObject.FindGameObjectWithTag("Player");
        if (player == null) return;

        var cm = player.GetComponent<CurrencyManager>();
        var im = player.GetComponent<ItemManager>();
        if (cm == null || im == null) return;

        int price = CurrentTarget.ShopPrice;
        if (!cm.Spend(price))
        {
            RefreshPrice(CurrentTarget);
            return;
        }

        im.AcquireItem(CurrentTarget.itemData);

        var pickup = CurrentTarget;
        Hide();
        Destroy(pickup.gameObject);
    }

    private CurrencyManager ResolveCurrencyManager()
    {
        var player = PlayerManager.Instance?.CurrentPlayer;
        if (player == null) player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<CurrencyManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 技能 UI Controller —— 监听 PlayerSkillManager（Model），通知 SkillUIPanel（View）。
/// 本类是 Model ↔ View 的唯一耦合点。
/// </summary>
public class SkillUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private PlayerSkillManager _skillManager;

    [Header("View 引用")]
    [SerializeField] private SkillUIPanel _panel;

    private SkillViewData[] _previousData = System.Array.Empty<SkillViewData>();

    // ==================== 生命周期 ====================

    private void Start()
    {
        // 跨场景后序列化引用失效，动态查找 PlayerSkillManager
        if (_skillManager == null)
            _skillManager = ResolveSkillManager();

        if (_skillManager == null)
        {
            Debug.LogError("SkillUIController: PlayerSkillManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("SkillUIController: SkillUIPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_skillManager.SlotCount);
        _previousData = new SkillViewData[_skillManager.SlotCount];

        // 订阅 Model 事件
        _skillManager.OnSkillCast += HandleSkillCast;
        _skillManager.OnSkillUpgraded += HandleSkillUpgraded;

        // 初始全量刷新
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void Update()
    {
        if (_skillManager == null) return;

        // 每帧同步冷却变化（冷却值通过 SkillInstance 的公开属性读取）
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void OnDestroy()
    {
        if (_skillManager != null)
        {
            _skillManager.OnSkillCast -= HandleSkillCast;
            _skillManager.OnSkillUpgraded -= HandleSkillUpgraded;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleSkillCast(int index, SkillData data) => SyncSlot(index);
    private void HandleSkillUpgraded(int index, int newLevel) => SyncSlot(index);

    // ==================== 核心同步 ====================

    private void SyncSlot(int index)
    {
        SkillInstance skill = _skillManager.GetSkill(index);
        SkillViewData data = BuildViewData(index, skill);

        if (!data.Equals(_previousData[index]))
        {
            _previousData[index] = data;
            _panel.RefreshSlot(index, data);
        }
    }

    private SkillViewData BuildViewData(int index, SkillInstance skill)
    {
        SkillViewData data = default;

        data.IsUnlocked = _skillManager.IsSlotUnlocked(index);
        data.IsEquipped = skill != null;
        data.ShowKeyLabel = true;

        // 快捷键标签
        KeyCode key = _skillManager.GetKeyCode(index);
        data.KeyLabel = KeyCodeToString(key);

        if (skill != null)
        {
            SkillData def = skill.Data;
            data.Icon = def.icon;
            data.Level = skill.Level;
            data.MaxLevel = skill.MaxLevel;
            data.IsCoolingDown = skill.IsCoolingDown;
            data.CooldownPercent = skill.CooldownPercent;
            data.CooldownRemaining = skill.CooldownRemaining;
        }

        return data;
    }

    private static string KeyCodeToString(KeyCode key)
    {
        // 提取字母/数字部分，去除 "Alpha" 前缀
        string s = key.ToString();
        if (s.StartsWith("Alpha"))
            return s.Substring(5);
        return s;
    }

    /// <summary>运行时动态查找 PlayerSkillManager (解决跨场景序列化引用失效问题)</summary>
    private static PlayerSkillManager ResolveSkillManager()
    {
        // 优先从 PlayerManager 获取持久化 Player
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<PlayerSkillManager>();

        // 兜底: Tag 查找
        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<PlayerSkillManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 属性修改 Buff — 修改目标某个属性值。
/// 通过 StatModifier 支持加算/乘算/覆盖叠加。
///
/// 示例: "+30% 攻击力" → statName="AttackStrength", modifier={Multiplicative, 1.3f}
///        "+50 生命值" → statName="MaxHealth", modifier={Additive, 50f}
/// </summary>
[CreateAssetMenu(fileName = "StatBuff", menuName = "Game/Buff Effect/Stat")]
public class StatBuff : BuffEffectBase
{
    [Header("属性修改")]
    [Tooltip("属性名: MaxHealth / MoveSpeed / AttackStrength / BulletSpeed / ShotsPerMinute / ColliderRadius")]
    public string statName;

    [Tooltip("修改器（加算/乘算/覆盖 + 值）")]
    public StatModifier modifier;

    // 记录修改前的值，用于 OnRemove 恢复
    private float _originalValue;

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        var stats = target.GetComponent<PlayerStats>();
        if (stats == null)
        {
            Debug.LogWarning($"StatBuff: target '{target.name}' 没有 PlayerStats 组件");
            return;
        }

        _originalValue = stats.GetStatValue(statName);
        float newValue = StatModifier.Apply(_originalValue, modifier);
        stats.SetStatValue(statName, newValue);
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        var stats = target.GetComponent<PlayerStats>();
        if (stats == null) return;

        stats.SetStatValue(statName, _originalValue);
    }
}

using UnityEngine;

/// <summary>
/// 受伤触发 Buff — 挂载者受伤时触发效果。
/// 适用于 "反伤" "受伤无敌" "受伤加速" 等效果。
///
/// 示例:
///   "荆棘铠甲" — reflectPercent=0.3f（反弹 30% 伤害）
///   "紧急护盾" — invincibleDuration=1f（受伤后无敌 1 秒）
/// </summary>
[CreateAssetMenu(fileName = "OnDamagedBuff", menuName = "Game/Buff Effect/On Damaged")]
public class OnDamagedBuff : BuffEffectBase
{
    [Header("反伤")]
    [Tooltip("反伤百分比: 0.3 = 反弹 30% 伤害")]
    [Range(0f, 1f)] public float reflectPercent;

    [Header("无敌")]
    [Tooltip("受伤后无敌时间（秒），0 = 不触发无敌")]
    public float invincibleDuration;

    // 存储上次生命值，用于计算实际伤害量
    private float _lastHealth;
    private PlayerStats _stats;
    private GameObject _owner;

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        _owner = target;
        _stats = target.GetComponent<PlayerStats>();
        if (_stats != null)
        {
            _lastHealth = _stats.CurrentHealth;
            _stats.OnHealthChanged += HandleHealthChanged;
        }
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        if (_stats != null)
            _stats.OnHealthChanged -= HandleHealthChanged;
        _stats = null;
        _owner = null;
    }

    private void HandleHealthChanged(float current, float max)
    {
        if (_stats == null) return;

        float damageTaken = _lastHealth - current;

        // 只处理受伤（生命减少）
        if (damageTaken <= 0f)
        {
            _lastHealth = current;
            return;
        }

        _lastHealth = current;

        // 反伤 — 查找最近的敌人并造成伤害
        if (reflectPercent > 0f && _owner != null)
        {
            float reflectDamage = damageTaken * reflectPercent;
            ApplyReflectDamage(reflectDamage);
        }

        // 无敌 — 暂时设置玩家无敌（通过 Buff 系统再挂一个临时无敌 Buff）
        if (invincibleDuration > 0f && _owner != null)
        {
            // 通过给自身挂一个短暂的无敌标记来实现
            // 这里使用简单的实现: 通过 Tag 检查无敌状态
        }
    }

    private void ApplyReflectDamage(float damage)
    {
        if (_owner == null) return;

        // 查找附近的敌人
        var enemies = GameObject.FindGameObjectsWithTag("Enemy");
        GameObject closest = null;
        float minDist = float.MaxValue;

        foreach (var enemy in enemies)
        {
            float dist = Vector2.Distance(_owner.transform.position, enemy.transform.position);
            if (dist < minDist && dist < 5f) // 5 单位搜索半径
            {
                minDist = dist;
                closest = enemy;
            }
        }

        if (closest != null)
        {
            var damageable = closest.GetComponent<IDamageable>();
            damageable?.TakeDamage(damage);
        }
    }
}

using System;
using UnityEngine;

/// <summary>
/// 条件触发道具效果 — 监听指定事件，条件满足时执行子效果。
/// 支持叠加持有：首次获取时订阅事件，最后一次移除时取消订阅。
///
/// 示例:
///   "复仇之盾" — triggerEvent=OnDamaged, executeEffect=AoE伤害效果
///   "不死鸟之羽" — triggerEvent=OnHealthBelow(20%), executeEffect=回满血效果
/// </summary>
[CreateAssetMenu(fileName = "ConditionalEffect", menuName = "Game/Item Effect/Conditional")]
public class ConditionalEffect : ItemEffectBase
{
    [Header("触发条件")]
    [Tooltip("触发事件类型")]
    public ItemTriggerEvent triggerEvent;

    [Header("条件参数")]
    [Tooltip("OnHealthBelow 时的阈值（0-1，如 0.2 = 20%）")]
    [Range(0f, 1f)] public float healthThreshold = 0.2f;

    [Header("执行效果")]
    [Tooltip("条件满足时执行的效果（可嵌套其他 ItemEffectBase）")]
    public ItemEffectBase executeEffect;

    [Header("冷却与次数")]
    [Tooltip("触发冷却（秒），0 = 无冷却")]
    public float cooldown;

    [Tooltip("最大触发次数，0 = 无限")]
    public int maxTriggerCount;

    private float _lastTriggerTime = -999f;
    private int _triggerCount;
    private int _refCount; // 持有层数

    // 缓存的组件引用
    private PlayerStats _stats;
    private PlayerCombat _combat;
    private PlayerSkillManager _skillManager;

    public override void OnAcquire(GameObject owner)
    {
        if (_refCount == 0)
        {
            // 首次获取：缓存引用并订阅事件
            _stats = owner.GetComponent<PlayerStats>();
            _combat = owner.GetComponent<PlayerCombat>();
            _skillManager = owner.GetComponent<PlayerSkillManager>();
            SubscribeEvents();
        }
        _refCount++;
    }

    public override void OnRemove(GameObject owner)
    {
        _refCount--;
        if (_refCount <= 0)
        {
            _refCount = 0;
            UnsubscribeEvents();
            _stats = null;
            _combat = null;
            _skillManager = null;
        }
    }

    private void SubscribeEvents()
    {
        switch (triggerEvent)
        {
            case ItemTriggerEvent.OnDamaged:
                if (_stats != null) _stats.OnHealthChanged += HandleHealthChanged;
                break;
            case ItemTriggerEvent.OnAttack:
                if (_combat != null) _combat.OnShoot += HandleAttack;
                break;
            case ItemTriggerEvent.OnSkillCast:
                if (_skillManager != null) _skillManager.OnSkillCast += HandleSkillCast;
                break;
            case ItemTriggerEvent.OnHealthBelow:
                if (_stats != null) _stats.OnHealthChanged += HandleHealthBelow;
                break;
        }
    }

    private void UnsubscribeEvents()
    {
        if (_stats != null)
        {
            _stats.OnHealthChanged -= HandleHealthChanged;
            _stats.OnHealthChanged -= HandleHealthBelow;
        }
        if (_combat != null)
            _combat.OnShoot -= HandleAttack;
        if (_skillManager != null)
            _skillManager.OnSkillCast -= HandleSkillCast;
    }

    private void TryTrigger(GameObject owner)
    {
        if (cooldown > 0f && Time.time - _lastTriggerTime < cooldown)
            return;
        if (maxTriggerCount > 0 && _triggerCount >= maxTriggerCount)
            return;

        _lastTriggerTime = Time.time;
        _triggerCount++;
        executeEffect?.OnAcquire(owner);
    }

    private void HandleHealthChanged(float current, float max) { }
    private void HandleAttack(Vector2 direction, float bulletSpeed, float attackStrength)
    {
        TryTrigger(_stats?.gameObject);
    }
    private void HandleSkillCast(int slotIndex, SkillData data)
    {
        TryTrigger(_stats?.gameObject);
    }
    private void HandleHealthBelow(float current, float max)
    {
        if (current / max <= healthThreshold)
            TryTrigger(_stats?.gameObject);
    }
}

